import{_ as s,a0 as a,w as p,s as u,ao as r,I as e,x as l,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"解決構建全球社區帶來的挑戰 | LCTT x X-CMD","titleTemplate":false,"description":"解決構建全球社區帶來的挑戰 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"解決構建全球社區帶來的挑戰 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"解決構建全球社區帶來的挑戰 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20171208 Overcoming challenges when building great global communities","title":"解決構建全球社區帶來的挑戰","tag":"201806","desc":""},"relativePath":"201806/20171208 Overcoming challenges when building great global communities.md","filePath":"[post].md"}'),d={name:"201806/20171208 Overcoming challenges when building great global communities.md"};function m(g,t,f,T,b,h){const n=a("Link");return p(),u("div",null,[t[19]||(t[19]=r('<h1 id="解決構建全球社區帶來的挑戰" tabindex="-1">解決構建全球社區帶來的挑戰 <a class="header-anchor" href="#解決構建全球社區帶來的挑戰" aria-label="Permalink to “解決構建全球社區帶來的挑戰”">​</a></h1><blockquote><p>全球開源社區通常面臨着語音壁壘、文化差異以及其它的挑戰。如何去解決它們呢？</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/BUSINESS_community2.png?itok=1blC7-NY" alt="配圖 "></p><p>今天的開源組織參與人員來自於全世界。你能預見到組建在線社區可能遇到哪些困難嗎？有沒有什麼辦法能夠克服這些困難呢？</p><p>為開源社區貢獻力量的人共同合作推動軟件的開發和發展。在過去，人們是面對面或者通過郵件和電話來交流的。今天，科技孕育出了在線交流——人們只需要進入一個聊天室或消息渠道就能一起工作了。比如，你可以早上跟摩洛哥的人一起工作，到了晚上又跟夏威夷的人一起工作。</p><h3 id="全球社區的三個挑戰" tabindex="-1">全球社區的三個挑戰 <a class="header-anchor" href="#全球社區的三個挑戰" aria-label="Permalink to “全球社區的三個挑戰”">​</a></h3><p>任何一個團隊合作過的人都知道意見分歧是很難被克服的。對於在線社區來説，語言障礙、不同的時區，以及文化差異也帶來了新的挑戰。</p><h4 id="語言障礙" tabindex="-1">語言障礙 <a class="header-anchor" href="#語言障礙" aria-label="Permalink to “語言障礙”">​</a></h4><p>英語是開源社區中的主流語言，因此英語不好的人會很難看懂文檔和修改意見。為了克服這個問題，吸引其他地區的社區成員，你需要邀請雙語者參與到社區中來。問問周圍的人——你會發現意想不到的精通其他語言的人。社區的雙語成員可以幫助別人跨越語言障礙，並且可以通過翻譯軟件和文檔來擴大項目的受眾範圍。</p><p>人們使用的編程語言也不一樣。你可能喜歡用 Bash 而其他人則可能更喜歡 Python、Ruby、C 等其他語言。這意味着，人們可能由於編程語言的原因而難以為你的代碼庫做貢獻。項目負責人為項目選擇一門被軟件社區廣泛認可的語言至關重要。如果你選擇了一門偏門的語言，則很少人能夠參與其中。</p><h4 id="不同的時區" tabindex="-1">不同的時區 <a class="header-anchor" href="#不同的時區" aria-label="Permalink to “不同的時區”">​</a></h4><p>時區為開源社區帶來了另一個挑戰。比如，若你在芝加哥，想與一個在倫敦的成員安排一次視頻會議，你需要調整 8 小時的時差。根據合作者的地理位置，你可能要在深夜或者清晨工作。</p><p>肉身轉移，可以讓你的團隊在同一個時區工作可以幫助克服這個挑戰，但這種方法只有極少數社區才能夠負擔的起。我們還可以定期舉行虛擬會議討論項目，建立一個固定的時間和地點以供所有人來討論未決的事項，即將發佈的版本等其他主題。</p><p>不同的時區也可以成為你的優勢，因為團隊成員可以全天候的工作。若你擁有一個類似 IRC 這樣的實時交流平台，用户可以在任意時間都能找到人來回答問題。</p><h4 id="文化差異" tabindex="-1">文化差異 <a class="header-anchor" href="#文化差異" aria-label="Permalink to “文化差異”">​</a></h4><p>文化差異是開源組織面臨的最大挑戰。世界各地的人都有不同的思考方式、計劃以及解決問題的方法。政治環境也會影響工作環境並影響決策。</p><p>作為項目負責人，你應該努力構建一種能包容不同看法的環境。文化差異可以鼓勵社區溝通。建設性的討論總是對項目有益，因為它可以幫助社區成員從不同角度看待問題。不同意見也有助於解決問題。</p><p>要成功開源，團隊必須學會擁抱差異。這不簡單，但多樣性最終會使社區收益。</p><h3 id="加強在線溝通的其他方法" tabindex="-1">加強在線溝通的其他方法 <a class="header-anchor" href="#加強在線溝通的其他方法" aria-label="Permalink to “加強在線溝通的其他方法”">​</a></h3>',19)),e("ul",null,[t[4]||(t[4]=r("<li><strong>本地化：</strong> 在線社區成員可能會發現位於附近的貢獻者——去見個面並組織一個本地社區。只需要兩個人就能組建一個社區了。可以邀請其他當地用户或僱員參與其中；他們甚至還能為以後的聚會提供場所呢。</li><li><strong>組織活動：</strong> 組織活動是構建本地社區的好方法，而且費用也不高。你可以在當地的咖啡屋或者啤酒廠聚會，慶祝最新版本的發佈或者某個核心功能的實現。組織的活動越多，人們參與的熱情就越高（即使只是因為單純的好奇心）。最終，可能會找到一家公司為你提供聚會的場地，或者為你提供贊助。</li><li><strong>保持聯繫：</strong> 每次活動後，聯繫本地社區成員。收起電子郵箱地址或者其他聯繫方式並邀請他們參與到你的交流平台中。邀請他們為其他社區做貢獻。你很可能會發現很多當地的人才，運氣好的話，甚至可能發現新的核心開發人員！</li><li><strong>分享經驗：</strong> 本地社區是一種非常有價值的資源，對你，對其他社區來説都是。與可能受益的人分享你的發現和經驗。如果你不清楚（LCTT 譯註：這裏原文是説 sure，但是根據上下文，這裏應該是 not sure）如何策劃一場活動或會議，可以諮詢其他人的意見。也許能找到一些有經驗的人幫你走到正軌。</li><li><strong>關注文化差異：</strong> 記住，文化規範因地點和人而異，因此在清晨安排某項活動可能適用於一個地方的人，但是不合適另一個地方的人。當然，你可以（也應該）利用其他社區的參考資料來更好地理解這種差異性，但有時你也需要通過試錯的方式來學習。不要忘了分享你所學到的東西，讓別人也從中獲益。</li><li><strong>檢查個人觀點：</strong> 避免在工作場合提出帶有很強主觀色彩的觀點（尤其是與政治相關的觀點）。這會抑制開放式的溝通和問題的解決。相反，應該專注於鼓勵與團隊成員展開建設性討論。如果你發現陷入了激烈的爭論中，那麼後退一步，冷靜一下，然後再從更加積極的角度出發重新進行討論。討論必須是有建設性的，從多個角度討論問題對社區有益。永遠不要把自己的主觀觀念放在社區的總體利益之前。</li>",6)),e("li",null,[t[1]||(t[1]=e("strong",null,"嘗試異步溝通：",-1)),t[2]||(t[2]=l(" 這些天，實時通訊平台已經引起了大家的關注，但除此之外還別忘了電子郵件。如果沒有在網絡平台上找到人的話，可以給他們發送一封電子郵件。有可能你很快就能得到回覆。考慮使用那些專注於異步溝通的平台，比如 ",-1)),i(n,{href:"https://twistapp.com"},{default:o(()=>[...t[0]||(t[0]=[l("Twist",-1)])]),_:1}),t[3]||(t[3]=l("，也不要忘了查看並更新論壇和維基。",-1))]),t[5]||(t[5]=e("li",null,[e("strong",null,"使用不同的解決方案："),l(" 並不存在一個單一的完美的解決方法，學習最有效的方法還是通過經驗來學習。從反覆試驗中你可以學到很多東西。不要害怕失敗；你會從失敗中學到很多東西從而不停地進步。")],-1))]),t[20]||(t[20]=e("h3",{id:"社區需要營養",tabindex:"-1"},[l("社區需要營養 "),e("a",{class:"header-anchor",href:"#社區需要營養","aria-label":"Permalink to “社區需要營養”"},"​")],-1)),t[21]||(t[21]=e("p",null,"將社區想像成是一顆植物的幼苗。你需要每天給它澆水，提供陽光和氧氣。社區也是一樣：傾聽貢獻者的聲音，記住你在與活生生的人進行互動，他們需要以合適的方式進行持續的交流。如果社區缺少了人情味，人們會停止對它的貢獻。",-1)),t[22]||(t[22]=e("p",null,"最後，請記住，每個社區都是不同的，沒有一種單一的解決方法能夠適用於所有社區。堅持不斷地從社區中學習並適應這個社區。",-1)),t[23]||(t[23]=e("hr",null,null,-1)),e("p",null,[t[7]||(t[7]=l("via: ",-1)),i(n,{href:"https://opensource.com/article/17/12/working-worldwide-communities"},{default:o(()=>[...t[6]||(t[6]=[l("https://opensource.com/article/17/12/working-worldwide-communities",-1)])]),_:1})]),e("p",null,[t[11]||(t[11]=l("作者：",-1)),i(n,{href:"https://opensource.com/users/jose"},{default:o(()=>[...t[8]||(t[8]=[l("José Antonio Rey",-1)])]),_:1}),t[12]||(t[12]=l(" 譯者：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[9]||(t[9]=[l("lujun9972",-1)])]),_:1}),t[13]||(t[13]=l(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[10]||(t[10]=[l("wxy",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=l("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[14]||(t[14]=[l("LCTT",-1)])]),_:1}),t[17]||(t[17]=l(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:o(()=>[...t[15]||(t[15]=[l("Linux中國",-1)])]),_:1}),t[18]||(t[18]=l(" 榮譽推出",-1))])])}const w=s(d,[["render",m]]);export{k as __pageData,w as default};
